def check(ctx):
    pose = ctx.object_pose("u_green")
    if pose is None:
        return None
    if "ref" not in ctx.state:
        ctx.state["ref"] = pose["pose"]["position"]
        return None
    d = ctx.dist(ctx.state["ref"], pose["pose"]["position"])
    tol = ctx.value("disturbance_tolerance_m")
    if d > tol:
        return {"value": d, "detail": "u_green moved beyond disturbance tolerance"}
    return None

